SELECT id, email, city, signup_date, is_active, age, MAX(credit_limit) OVER (PARTITION BY city ORDER BY credit_limit, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_max_credit_limit, AVG(credit_limit) OVER (PARTITION BY city ORDER BY credit_limit, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_avg_credit_limit, MIN(credit_limit) OVER (PARTITION BY city ORDER BY credit_limit, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_min_credit_limit, LAST_VALUE(credit_limit) IGNORE NULLS OVER (PARTITION BY segment ORDER BY signup_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_credit_limit FROM customers WHERE name IS NOT NULL
